/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ =========================================
   👑 黄金定稿 V12：寻找完美缝隙的黄金数字 (90)
   ========================================= */

/* 1. 顶栏：层级 90（不穿透设置页，但高人一等） */
.chat-detail-screen .chat-header-custom,
.chat-detail-screen .glass-header {
    position: sticky !important;
    top: 0 !important;
    z-index: 90 !important; 
    flex-shrink: 0 !important;
}

/* 2. 底栏：层级 90（突破菜单的隐形遮罩，但依然低于设置页） */
.chat-detail-screen .input-area-custom {
    position: sticky !important;
    bottom: 0 !important;
    z-index: 90 !important; 
    flex-shrink: 0 !important;
}

/* 3. 🎯 镇压聊天记录：强制把它压到 10 层最底下！
   绝不允许它干扰菜单的点击！ */
.chat-detail-screen .chat-messages-area,
.chat-detail-screen .chat-message-list-custom {
    position: relative !important;
    z-index: 10 !important; 
}

/* 4. 菜单本体，给它最高的 100 层，直接浮出水面！ */
.chat-detail-screen .more-options-popup {
    z-index: 100 !important;
    pointer-events: auto !important;
}

/* 5. 锁定打字时的体积防抖，治愈抽搐乱跳 */
.chat-detail-screen .input-box-custom,
.chat-detail-screen .input-action-bar-custom,
.chat-detail-screen .input-row-wrapper {
    box-sizing: border-box !important;
}
/* =========================================
   第一步：开放接口区 (你只需要在这里用 px 调数值！)
   ========================================= */
:root {
  /* --- 1. 返回键贴图调节 --- */
  --icon-back: url('https://i.imgant.com/v2/driW44e.png');
  --icon-back-w: 22px;     /* 宽度 */
  --icon-back-h: 22px;     /* 高度 */
  --icon-back-x: -1px;     /* 左右位置：正数向右，负数向左 */
  --icon-back-y: 0px;      /* 上下位置：正数向下，负数向上 */

  /* --- 2. 视频键贴图调节 --- */
  --icon-video: url('https://i.imgant.com/v2/Kx2Iu54.png');
  --icon-video-w:40px;
  --icon-video-h:40px;
  --icon-video-x: 0px;
  --icon-video-y: 0px;

  /* --- 3. 设置键贴图调节 --- */
  --icon-info: url('https://i.imgant.com/v2/GW7VPyl.png');
  --icon-info-w: 30px;
  --icon-info-h: 30px;
  --icon-info-x: 0px;
  --icon-info-y: 0px;

  /* 顶栏原生变量清理 (无需修改) */
  --chat-header-bg: transparent;
  --chat-header-blur: 0px;
  --chat-header-border: transparent;
  --header-btn-gap: 0px; /* 强制设为 0，为了让视频和设置能紧紧拼在一起 */
}

/* =========================================
   第二步：顶栏透明化 & 隐藏无关元素
   ========================================= */
